from pathlib import Path
p=Path('E:/cxy/09-设计与原型/自定义活动管理/活动执行填报.html')
s=p.read_text(encoding='utf-8')
script='''<style>
#execution-layout{display:grid;grid-template-columns:240px minmax(0,1fr);gap:20px;padding:16px;background:#f4f6f9}#execution-sidebar{background:white;padding:20px;box-shadow:0 2px 8px #0001;font:14px/1.8 "Microsoft YaHei",sans-serif;color:#263445}#execution-sidebar p{margin:0 0 20px;overflow-wrap:anywhere}#execution-layout main{padding:0}#execution-layout details{margin:0 0 20px;background:white;border:1px solid #dce3ec;border-radius:4px}#execution-layout summary{padding:20px;color:#263445;cursor:pointer;font-weight:600}#execution-layout summary span{color:#176bc5;margin-left:16px}#application-snapshot{padding:16px}#application-snapshot section{margin-top:12px}#application-snapshot input:disabled,#application-snapshot select:disabled,#application-snapshot textarea:disabled{opacity:1;color:#586779;-webkit-text-fill-color:#586779;background:#f4f6f9}#execution-layout .collapse-hint{display:block;padding:16px;text-align:center;color:#586779;background:#f7f9fb;border:1px dashed #dce3ec;margin:0 16px 16px}#execution-layout details[open]+.collapse-hint{display:none}@media(max-width:850px){#execution-layout{grid-template-columns:1fr}#execution-sidebar{display:none}}
</style><script>
(()=>{const app=document.getElementById('custom-activity'),main=app.querySelector('main');const old=main.querySelector('section');if(old)old.remove();const layout=document.createElement('div');layout.id='execution-layout';const sidebar=document.createElement('div');sidebar.id='execution-sidebar';app.append(layout);layout.append(sidebar,main);const details=document.createElement('details');details.id='application-details';details.innerHTML='<summary>活动信息 <span>自定义活动 · 申请表单（只读）</span></summary><div id="application-snapshot"></div>';const hint=document.createElement('button');hint.type='button';hint.className='collapse-hint';hint.textContent='⌄ 点击展开查看完整活动申请信息';hint.onclick=()=>{details.open=true;hint.hidden=true};details.addEventListener('toggle',()=>hint.hidden=details.open);const form=document.getElementById('execution');form.before(details,hint);
function sync(){let source;try{source=parent.document.getElementById('application').contentDocument.getElementById('custom-activity')}catch{}if(!source)return;const target=document.getElementById('application-snapshot');target.replaceChildren();const copiedStyle=source.querySelector('style').cloneNode(true);target.append(copiedStyle);source.querySelectorAll('form>section').forEach(section=>{const clone=section.cloneNode(true);const originals=section.querySelectorAll('input,select,textarea'),copies=clone.querySelectorAll('input,select,textarea');copies.forEach((el,i)=>{if(el.type!=='file')el.value=originals[i].value;if(el.type==='radio'||el.type==='checkbox')el.checked=originals[i].checked;el.disabled=true;el.removeAttribute('required');el.removeAttribute('id')});clone.querySelectorAll('button,input[type=file]').forEach(el=>el.remove());clone.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));target.append(clone)});const fields=source.querySelectorAll('.basic-field');sidebar.replaceChildren();const heading=document.createElement('p');heading.textContent='申请单号：示例 HD-DEMO-001';sidebar.append(heading);fields.forEach(field=>{const p=document.createElement('p');const label=field.querySelector('span')?.textContent.replace('*','')||'';const controls=Array.from(field.querySelectorAll('input'));const value=controls.length?controls.filter(el=>!['radio','checkbox'].includes(el.type)||el.checked).map(el=>el.value).join(' 至 '):field.querySelector('b')?.textContent||field.lastElementChild?.textContent||'';p.textContent=label+' '+value;sidebar.append(p)});const budgets=Array.from(source.querySelectorAll('#cost-rows [data-amount]')).map(el=>el.textContent);const costRows=document.querySelectorAll('#costs tr');costRows.forEach((row,i)=>{const sourceRow=source.querySelectorAll('#cost-rows tr')[i];if(sourceRow){row.cells[0].textContent=sourceRow.querySelector('input')?.value||'';row.cells[1].textContent=budgets[i]||'';row.cells[3].textContent=source.querySelector('#company-percent').value+'%';row.cells[4].textContent=source.querySelector('#payment').value}})}window.syncApplicationSnapshot=sync;sync();})();
</script>'''
s=s.replace('</body>',script+'</body>')
p.write_text(s,encoding='utf-8')
# Resync the application snapshot when selecting execution in the combined page.
m=Path('E:/cxy/09-设计与原型/自定义活动管理/tools/merge-activity-pages.py')
t=m.read_text(encoding='utf-8')
t=t.replace("document.title=button.textContent+' · 活动管理'","document.title=button.textContent+' · 活动管理';if(button.dataset.page==='execution'){const win=document.getElementById('execution').contentWindow;if(win.syncApplicationSnapshot)win.syncApplicationSnapshot()}")
m.write_text(t,encoding='utf-8')
